{
  "name": "opencode-opointer",
  "version": "1.0.2",
  "private": false,
  "description": "OpenCode plugin for DOM editing via browser extension. Enables AI-powered DOM editing through a WebSocket bridge.",
  "type": "module",
  "main": "dist/index.js",
  "scripts": {
    "dev": "node --watch dist/index.js",
    "build": "tsc && npm run bundle",
    "bundle": "esbuild src/index.ts --bundle --outfile=dist/bundle.js --platform=node --format=esm --external:@opencode-ai/plugin",
    "prepack": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "dom-editor",
    "browser-extension",
    "ai",
    "websocket"
  ],
  "author": "mio",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/mioqwe/opointer"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@opencode-ai/sdk": "^1.0.0",
    "element-source": "^0.0.5",
    "ws": "^8.17.0"
  },
  "devDependencies": {
    "@types/node": "^20.12.0",
    "@types/ws": "^8.5.10",
    "esbuild": "^0.28.0",
    "typescript": "^5.4.0"
  },
  "opencode": {
    "plugins": [
      "opencode-opointer"
    ]
  }
}
